package com.bbb.exercise.agentdemo1_0.config;
import org.springframework.boot.context.properties.ConfigurationProperties;
import java.time.Duration;
@ConfigurationProperties(prefix="app.oss") public class OssProperties {
 private boolean enabled=true; private String region="cn-beijing",bucket="bbb-image-prod",endpoint="oss-cn-beijing.aliyuncs.com",accessKeyId="",accessKeySecret="",sourcePrefix="source",outputPrefix="output",thumbnailPrefix="thumbnail",archivePrefix="one and one"; private Duration uploadPolicyTtl=Duration.ofMinutes(10),signedUrlTtl=Duration.ofMinutes(10); private long maxObjectBytes=20L*1024*1024;
 public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getRegion(){return region;} public void setRegion(String v){region=v;} public String getBucket(){return bucket;} public void setBucket(String v){bucket=v;} public String getEndpoint(){return endpoint;} public void setEndpoint(String v){endpoint=v;} public String getAccessKeyId(){return accessKeyId;} public void setAccessKeyId(String v){accessKeyId=v;} public String getAccessKeySecret(){return accessKeySecret;} public void setAccessKeySecret(String v){accessKeySecret=v;} public String getSourcePrefix(){return sourcePrefix;} public void setSourcePrefix(String v){sourcePrefix=v;} public String getOutputPrefix(){return outputPrefix;} public void setOutputPrefix(String v){outputPrefix=v;} public String getThumbnailPrefix(){return thumbnailPrefix;} public void setThumbnailPrefix(String v){thumbnailPrefix=v;} public String getArchivePrefix(){return archivePrefix;} public void setArchivePrefix(String v){archivePrefix=v;} public Duration getUploadPolicyTtl(){return uploadPolicyTtl;} public void setUploadPolicyTtl(Duration v){uploadPolicyTtl=v;} public Duration getSignedUrlTtl(){return signedUrlTtl;} public void setSignedUrlTtl(Duration v){signedUrlTtl=v;} public long getMaxObjectBytes(){return maxObjectBytes;} public void setMaxObjectBytes(long v){maxObjectBytes=v;}
}
